#include <iostream>
using namespace std;

int main() {
    int row, column;
    cin >> row >> column;

    bool res_row[10] = {};
    bool res_col[10] = {};

    for (int i = 0; i < row; ++i) {
        for (int j = 0; j < column; ++j) {
            char cell;
            cin >> cell;
            if (cell == 'S') {
                res_row[i] = true;
                res_col[j] = true;
            }
        }
    }

    int safe_rows = 0;
    int safe_columns = 0;

    for (int i = 0; i < row; ++i) {
        if (!res_row[i]) {
            ++safe_rows;
        }
    }

    for (int j = 0; j < column; ++j) {
        if (!res_col[j]) {
            ++safe_columns;
        }
    }

    cout << safe_rows * column + safe_columns * row
         - safe_rows * safe_columns << '\n';

    return 0;
}

